//! Batch 4 integrated check (development evidence, synthetic data): a Manager draft, an Owner
//! post through the outbox with a lost response and an explicit retry, a restart, the sale shown
//! from the device projection, a receipt, a Cash Book close, another restart, a backup, a
//! restore at a fresh path, and the bill image regenerated byte for byte. The Manager's
//! projection file holds no cost, margin or FIFO field.
use alm_core::{BillDate, DraftId, Role};
use alm_store::synthetic_read_model::Store;
use alm_store::{OutboxStatus, ProjectionStore};
use alm_sync::Outcome;

use crate::Trial;
use crate::screen_tests::Root;

fn day() -> BillDate {
    BillDate::new(2025, 4, 30).unwrap()
}

#[test]
fn draft_post_lost_response_restart_receipt_cash_close_backup_restore_and_image() {
    let device_a = Root::new("batch4-a");
    let mut trial = Trial::open(&device_a.0, Some(day())).unwrap();

    // Manager: a provisional draft only; posted screens and costs stay denied.
    trial.set_owner(false).unwrap();
    let draft = crate::billing_tests::draft().with_bill_date(Some(day()));
    trial.drafts.save_draft(draft.clone()).unwrap();
    for tab in ["sales", "customers", "stock"] {
        let html = trial.render(tab).unwrap();
        assert!(html.contains("role=\"alert\""), "{tab}");
    }
    assert!(trial.sale_prepare(&terms("20")).is_err());

    // Owner: review, then confirm with the response lost; the retry keeps the request ID.
    trial.set_owner(true).unwrap();
    trial.current = Some((
        trial.drafts.reopen_draft(DraftId::new(1)).unwrap().unwrap(),
        true,
    ));
    trial.sale_prepare(&terms("20")).unwrap();
    let serial = trial.posting.pending(Role::Owner).unwrap().serial();
    trial.authority.lose_next_response();
    assert!(trial.sale_confirm(serial).is_err());
    let request = trial.outbox.unresolved().unwrap().remove(0).request_id;
    let Ok(Outcome::Sale(receipt)) = trial.retry(&request) else {
        panic!("retry returns the committed sale")
    };
    assert_eq!((receipt.invoice, receipt.total.minor_units()), (1, 12_050));
    assert_eq!(
        trial.outbox.entries().unwrap().len(),
        1,
        "no second request"
    );
    drop(trial);

    // Restart: the projection on the device shows the sale.
    let stored = ProjectionStore::open_scoped(&device_a.0, "trial", Role::Owner)
        .unwrap()
        .load()
        .unwrap()
        .unwrap();
    assert_eq!(stored.snapshot.sales[0].invoice, 1);
    let mut trial = Trial::open(&device_a.0, Some(day())).unwrap();
    assert!(trial.render("sales").unwrap().contains("<b>#1</b>"));

    // A receipt and a Cash Book day close, both through the outbox.
    trial
        .receipt_save(crate::receipts::Terms {
            customer: "batch1-customer".into(),
            date: "2025-04-30".into(),
            amount: "10".into(),
            mode: crate::receipts::Mode::Cash,
        })
        .unwrap();
    trial
        .cash_entry(crate::cashbook::Entry {
            id: String::new(),
            date: "2025-04-30".into(),
            cash: "30".into(),
            paytm: String::new(),
            phonepe: String::new(),
            debt: String::new(),
            salary: String::new(),
            goods: String::new(),
            misc: String::new(),
            intent: "save".into(),
        })
        .unwrap();
    assert!(
        trial
            .outbox
            .entries()
            .unwrap()
            .iter()
            .all(|e| e.status == OutboxStatus::Confirmed)
    );
    drop(trial);

    // Restart again: the journal replays and the projection still matches.
    let mut trial = Trial::open(&device_a.0, Some(day())).unwrap();
    let projected = trial.projected().unwrap().snapshot;
    assert_eq!(projected.receipts.len(), 1);
    assert_eq!(projected.cash_days.len(), 1);
    assert_eq!(projected.cash_days[0].amounts.cash.minor_units(), 3_000);
    let customers = trial.render("customers").unwrap();
    assert!(customers.contains("Synthetic Customer"));
    crate::device::assert_book_view(&mut trial);
    // Archive regeneration is defined for the Latest balance (closing balance), as in batch 3.
    trial
        .settings_preference(alm_core::preferences::Preference::Balance(
            alm_core::confirmation::BalanceMode::Latest,
        ))
        .unwrap();
    let (_, png) = trial.bill_image_png(DraftId::new(1)).unwrap();

    // Backup, then restore on a fresh device at a fresh path.
    let backup = trial.backup_create().unwrap();
    let bytes = std::fs::read(device_a.0.join("backups").join(&backup)).unwrap();
    trial.set_owner(false).unwrap();
    trial.render("review").unwrap();
    drop(trial);
    let device_b = Root::new("batch4-b");
    std::fs::create_dir_all(device_b.0.join("backups")).unwrap();
    std::fs::write(device_b.0.join("backups").join(&backup), &bytes).unwrap();
    let mut other = Trial::open(&device_b.0, Some(day())).unwrap();
    other.backup_restore(&backup).unwrap();
    let restored = device_b.0.join("restored").join(format!(
        "{}-restored-1.json",
        backup.trim_end_matches(".json")
    ));
    let store = Store::open(&restored, Role::Owner).unwrap();
    let again = crate::outputs::bill_png(&store, Role::Owner, "sale-1", day()).unwrap();
    assert_eq!(again, png, "bill image regenerated byte for byte");
    let live = Store::open(&device_b.0.join("shop.json"), Role::Owner).unwrap();
    assert_eq!(
        crate::outputs::bill_png(&live, Role::Owner, "sale-1", day()).unwrap(),
        png,
        "the restored settings are the live ones"
    );

    // The Manager's projection on device A holds no cost, margin or FIFO field or value.
    let dir = device_a.0.canonicalize().unwrap().join("projections");
    let mut manager = Vec::new();
    for entry in std::fs::read_dir(&dir).unwrap() {
        let path = entry.unwrap().path();
        if path.to_string_lossy().contains("-manager.sqlite3") {
            manager.extend(std::fs::read(&path).unwrap());
        }
    }
    assert!(!manager.is_empty(), "the Manager projection file exists");
    let text = String::from_utf8_lossy(&manager).to_lowercase();
    for word in ["cost", "margin", "fifo", "profit", "owner_", "buy"] {
        assert!(!text.contains(word), "{word} in the Manager projection");
    }
    assert!(text.contains("synthetic lime"), "it does hold the catalog");
}

fn terms(paid: &str) -> crate::billing::Terms {
    crate::billing::Terms {
        date: "2025-04-30".into(),
        paid: paid.into(),
    }
}
